import { DsBreadcrumbs } from '@primasoftllc/design-system';

export function Example() {
  const pageUrl = typeof window === 'undefined' ? '' : window.location.href.split('#')[0];
  return <div style={{display: 'grid', gap: 16}}>
    <DsBreadcrumbs aria-label="Положение в каталоге" items={[
      {label: 'Автопарк', href: pageUrl + '#fleet-destination'},
      {label: 'Грузовые автомобили', href: pageUrl + '#trucks-destination'},
      {label: 'МАЗ 5440'},
    ]}/>
    <section id="fleet-destination" tabIndex={-1} aria-label="Автопарк"><strong>Автопарк</strong><p style={{margin: '8px 0 0'}}>148 объектов в 12 группах.</p></section>
    <section id="trucks-destination" tabIndex={-1} aria-label="Грузовые автомобили"><strong>Грузовые автомобили</strong><p style={{margin: '8px 0 0'}}>МАЗ 5440, Volvo FH16 и Scania R450.</p></section>
  </div>;
}

